-- V94: Update principle carousels only; coaching scripts remain untouched.
begin;
update public.leader_playbook set title = '5 Cấp Độ Lãnh Đạo (John Maxwell)', content = 'Quản trị đội ngũ Sale Bảo hiểm là một nghệ thuật. Hãy đi qua 5 tình huống thực chiến dưới đây để xem bạn đang vận hành ở cấp độ nào:', mini_quiz = null, learning_carousel = '{"situations":[{"question":"🔥 Cấp độ 1 (Quyền lực): Đội ngũ đang chững số cuối tháng. Bạn đăng vào group: ''Ai không đủ số tháng này sẽ bị cắt data''. Việc này sẽ dẫn đến kết quả gì?","options":["A. Team sợ và chạy số điên cuồng","B. Team chống đối ngầm và rục rịch nghỉ việc"],"correct_index":1,"correct_explanation":"Chính xác! Lạm dụng Cấp độ 1 có thể ra số ngắn hạn nhưng phá vỡ sự gắn kết. Đại lý sẽ làm ẩu, ép khách và cuối cùng là rời đi.","wrong_explanation":"Sai lầm! Sự sợ hãi (Cấp độ 1) không tạo ra doanh số bền vững. Nó chỉ khiến đại lý đối phó bằng những hợp đồng ảo."},{"question":"🔥 Cấp độ 2 (Quan hệ): Một đại lý mới đang rất nản vì bị khách hàng từ chối liên tục. Bạn làm gì để áp dụng Cấp độ 2?","options":["A. Nhắc nhở quy định phải gọi 20 cuộc/ngày","B. Rủ đi cà phê, lắng nghe những ấm ức của họ"],"correct_index":1,"correct_explanation":"Tuyệt vời! Cấp độ 2 là khi nhân sự làm vì ''nể'' và ''quý'' bạn. Sự thấu cảm lúc này quan trọng hơn KPI.","wrong_explanation":"Nhắc quy định lúc này là bạn đang dùng Cấp độ 1 (Ép buộc). Hãy lùi lại, dùng Cấp độ 2 (Xây dựng quan hệ) để xoa dịu họ trước."},{"question":"🔥 Cấp độ 3 (Kết quả): Lời nói của bạn bắt đầu mất trọng lượng với các đại lý kỳ cựu. Cách nhanh nhất để lấy lại uy tín (Cấp độ 3) là gì?","options":["A. Tự mình chốt một HĐ lớn (MDRT) để làm gương","B. Tổ chức họp team và yêu cầu mọi người tôn trọng Leader"],"correct_index":0,"correct_explanation":"Quá chuẩn! Cấp độ 3 là ''Dẫn dắt bằng kết quả''. Khi bạn tạo ra thành tích thực tế, đội ngũ sẽ tự động ngưỡng mộ và làm theo.","wrong_explanation":"Đòi hỏi sự tôn trọng bằng lời nói là vô ích. Ở Cấp độ 3, nhân sự chỉ nghe bạn khi bạn chứng minh được năng lực thực chiến (MDRT/COT)."},{"question":"🔥 Cấp độ 4 (Phát triển người khác): Bạn có một ''Ngôi sao bán hàng'' rất giỏi nhưng hay tự mãn. Bạn áp dụng Cấp độ 4 như thế nào?","options":["A. Dùng nội quy cứng rắn để kìm hãm cái tôi của họ","B. Giao cho họ quyền chủ trì huấn luyện người mới"],"correct_index":1,"correct_explanation":"Đỉnh cao! Cấp độ 4 là tạo ra những Leader mới. Khi trao quyền, bạn vừa giữ chân được nhân tài, vừa dẹp bỏ được cái tôi kiêu ngạo của họ.","wrong_explanation":"Kìm hãm họ sẽ khiến họ bỏ sang công ty khác. Hãy nâng tầm họ lên bằng cách trao quyền đào tạo người khác (Cấp độ 4)."},{"question":"🔥 Cấp độ 5 (Sự tôn trọng/Đỉnh cao): Đâu là dấu hiệu cho thấy bạn đã đạt đến Cấp độ 5 trong ngành Bảo hiểm?","options":["A. Doanh số team luôn đứng Top 1 công ty","B. Bạn rời đi, nhưng di sản và văn hóa team vẫn tự vận hành tốt"],"correct_index":1,"correct_explanation":"Hoàn hảo! Cấp độ 5 (Pinnacle) là khi bạn trở thành biểu tượng. Tầm ảnh hưởng của bạn vượt ra khỏi chức danh và doanh số hiện tại.","wrong_explanation":"Doanh số Top 1 chỉ mới là Cấp độ 3 (Kết quả). Cấp độ 5 là sự trường tồn của văn hóa và di sản bạn để lại ngay cả khi bạn không có mặt."}],"summary":{"title":"🎯 TỔNG KẾT & NEO KIẾN THỨC","content":"Lãnh đạo không phải là cái ghế bạn ngồi, mà là hành trình bạn đi từ (1) Quyền lực -> (2) Quan hệ -> (3) Kết quả -> (4) Phát triển người khác -> (5) Di sản.","homework":"📝 BÀI TẬP NHỎ CHO BẠN: Hãy nhìn lại tuần vừa qua. Bạn đang dùng Cấp độ mấy để tương tác với team nhiều nhất? Ngày mai, hãy thử làm MỘT hành động thuộc Cấp độ 4 (Khai vấn/Phát triển) với một thành viên đang gặp khó khăn nhé!"}}'::jsonb where legacy_source_code = 'v88-leader-playbook-01' and type = 'principle';
update public.leader_playbook set mini_quiz = null, learning_carousel = '{"situations":[{"question":"🔥 Tình huống: Một đại lý mới liên tục trễ deadline nộp báo cáo. Hành động đầu tiên của bạn là gì?","options":["A. Nhắc nhở quy định phạt của văn phòng.","B. Hẹn cà phê hỏi thăm khó khăn dạo này."],"correct_index":1,"correct_explanation":"Chính xác! Khám phá phần chìm (áp lực, khó khăn) trước khi xử lý bề nổi giúp giải quyết triệt để vấn đề.","wrong_explanation":"Khoan đã, việc áp dụng quy định phạt ngay lập tức chỉ mới giải quyết 10% bề nổi và dễ khiến TVV bất mãn. Hãy lùi lại tìm hiểu 90% phần chìm nhé."}],"summary":{"title":"TỔNG KẾT & NEO KIẾN THỨC","content":"Đi trễ, than vãn và giảm tương tác thường chỉ là phần nổi. Lãnh đạo thấu cảm cần khám phá áp lực, nỗi sợ hoặc mâu thuẫn phía sau trước khi kết luận.","homework":"BÀI TẬP NHỎ: Trong cuộc trò chuyện tới, hãy thay phản ứng đầu tiên bằng một câu hỏi mở để khám phá phần chìm của tín hiệu bạn đang thấy."}}'::jsonb where legacy_source_code = 'v88-leader-playbook-02' and type = 'principle';
update public.leader_playbook set mini_quiz = null, learning_carousel = '{"situations":[{"question":"🔥 Tình huống: TVV nói ''Em không có khách hàng''. Câu hỏi ''Why'' đầu tiên bạn nên dùng là gì?","options":["A. Tại sao em không thử gọi lại danh sách cũ?","B. Tại sao dạo này em lại thấy khó tìm khách vậy?"],"correct_index":1,"correct_explanation":"Chính xác! Đặt câu hỏi mở để họ tự đào sâu vấn đề, thay vì mớm sẵn giải pháp.","wrong_explanation":"Câu hỏi này vô tình đã mớm sẵn giải pháp. Kỹ thuật 5 Whys yêu cầu dùng câu hỏi mở để TVV tự đào sâu vấn đề."}],"summary":{"title":"TỔNG KẾT & NEO KIẾN THỨC","content":"5 Whys giúp Leader đi từ biểu hiện sang nguyên nhân gốc bằng những câu hỏi mở, thay vì vội vàng sửa hộ hay mớm sẵn giải pháp.","homework":"BÀI TẬP NHỎ: Chọn một trở ngại gần đây của TVV và chuẩn bị năm câu hỏi ''Tại sao?'' theo thứ tự từ bề mặt đến gốc rễ."}}'::jsonb where legacy_source_code = 'v92-leader-principle-03' and type = 'principle';
update public.leader_playbook set mini_quiz = null, learning_carousel = '{"situations":[{"question":"🔥 Tình huống: Đâu là câu nói chuẩn xác nhất của một Lãnh đạo phục vụ trong buổi họp đầu tuần?","options":["A. Tuần này ai cam kết mang về 2 hợp đồng?","B. Tuần này anh/chị có thể hỗ trợ team điều gì?"],"correct_index":1,"correct_explanation":"Chính xác! Trọng tâm của Lãnh đạo phục vụ là tháo gỡ rào cản để team hoàn thành tốt công việc.","wrong_explanation":"Đây là cách giao việc mang tính áp đặt. Lãnh đạo phục vụ sẽ tập trung hỏi xem team cần hỗ trợ gì để tự họ đạt được mục tiêu."}],"summary":{"title":"TỔNG KẾT & NEO KIẾN THỨC","content":"Lãnh đạo phục vụ không đứng trên để chỉ việc mà đứng cùng đội ngũ để tháo rào cản, tạo điều kiện và phát triển năng lực của từng người.","homework":"BÀI TẬP NHỎ: Trước buổi họp tiếp theo, chuẩn bị một câu hỏi cụ thể về sự hỗ trợ mà mỗi thành viên đang cần từ Leader."}}'::jsonb where legacy_source_code = 'v92-leader-principle-04' and type = 'principle';
update public.leader_playbook set mini_quiz = null, learning_carousel = '{"situations":[{"question":"🔥 Tình huống: Đâu là cách nói chuẩn chữ ''B'' (Behavior) trong khung SBI?","options":["A. Dạo này em làm việc rất thiếu tập trung.","B. Sáng nay em ngắt lời khách hàng 3 lần."],"correct_index":1,"correct_explanation":"Chính xác! Hành vi phải là sự thật đếm được, không dán nhãn cảm tính.","wrong_explanation":"''Thiếu tập trung'' là một nhãn dán cảm tính, không phải hành vi khách quan. Hãy dùng sự kiện có thể quan sát được."}],"summary":{"title":"TỔNG KẾT & NEO KIẾN THỨC","content":"SBI giúp phản hồi rõ ràng và bảo vệ lòng tự trọng: nêu bối cảnh, mô tả hành vi quan sát được, rồi cùng xem tác động thực tế.","homework":"BÀI TẬP NHỎ: Chọn một góp ý bạn cần nói trong tuần này và viết trước ba câu theo Situation, Behavior, Impact."}}'::jsonb where legacy_source_code = 'v92-leader-principle-05' and type = 'principle';
commit;
